import { Component, EventEmitter, Inject, OnInit, Output } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { DialogEvent } from '@placeos/common';
import { showStaff, User } from '@placeos/users';
import { ParkingSpace } from './parking-state.service';

@Component({
    selector: 'parking-space-modal',
    template: `
        <div class="w-[28rem]">
            <header
                class="sticky top-0 z-10 m-2 w-[calc(100%-1rem)] rounded border-none bg-base-200 p-2"
            >
                <h2 class="px-2 text-xl font-medium">
                    {{
                        (id
                            ? 'APP.CONCIERGE.PARKING_SPACE_EDIT'
                            : 'APP.CONCIERGE.PARKING_SPACE_NEW'
                        ) | translate
                    }}
                </h2>
                <button icon matRipple mat-dialog-close *ngIf="!loading">
                    <app-icon>close</app-icon>
                </button>
            </header>
            <main
                *ngIf="!loading; else load_state"
                class="flex flex-col p-4"
                [formGroup]="form"
            >
                <label for="name">{{
                    'APP.CONCIERGE.PARKING_SPACE_NAME' | translate
                }}</label>
                <mat-form-field appearance="outline">
                    <input
                        matInput
                        name="name"
                        [placeholder]="
                            'APP.CONCIERGE.PARKING_SPACE_NAME' | translate
                        "
                        formControlName="name"
                    />
                    <mat-error>{{
                        'FORM.NAME_REQUIRED' | translate
                    }}</mat-error>
                </mat-form-field>
                <label for="map-id">{{ 'EXPLORE.MAP_ID' | translate }}</label>
                <mat-form-field appearance="outline">
                    <input
                        matInput
                        name="map-id"
                        [placeholder]="'EXPLORE.MAP_ID_PLACEHOLDER' | translate"
                        formControlName="map_id"
                    />
                    <mat-error>
                        {{ 'EXPLORE.MAP_ID_REQUIRED' | translate }}
                    </mat-error>
                </mat-form-field>
                <label for="user">{{
                    'APP.CONCIERGE.USER_ASSIGNED' | translate
                }}</label>
                <div class="mb-4 flex items-center space-x-2">
                    <a-user-search-field
                        name="user"
                        formControlName="assigned_user"
                        class="flex-1"
                    ></a-user-search-field>
                    <button
                        icon
                        matRipple
                        class="h-12 w-12 min-w-12 rounded bg-secondary text-secondary-content"
                        [matTooltip]="'APP.CONCIERGE.USER_CLEAR' | translate"
                        (click)="
                            form.patchValue({
                                assigned_user: null,
                                assigned_to: null,
                                assigned_name: null,
                            })
                        "
                    >
                        <app-icon className="material-symbols-outlined">
                            person_cancel
                        </app-icon>
                    </button>
                </div>
                <label for="notes">{{ 'FORM.NOTES' | translate }}</label>
                <mat-form-field appearance="outline">
                    <textarea
                        matInput
                        name="notes"
                        [placeholder]="'FORM.NOTES' | translate"
                        formControlName="notes"
                    ></textarea>
                </mat-form-field>
            </main>
            <footer
                class="flex items-center justify-end space-x-2 border-t border-base-300 px-4 py-2"
            >
                <button btn matRipple class="w-32" (click)="postForm()">
                    {{ 'COMMON.SAVE' | translate }}
                </button>
            </footer>
        </div>
        <ng-template #load_state>
            <main
                class="flex flex-col items-center justify-center space-y-2 p-8"
            >
                <mat-spinner diameter="32"></mat-spinner>
                <p>{{ 'APP.CONCIERGE.PARKING_SPACE_SAVE' | translate }}</p>
            </main>
        </ng-template>
    `,
    styles: [``],
    standalone: false,
})
export class ParkingSpaceModalComponent implements OnInit {
    @Output() public readonly event = new EventEmitter<DialogEvent>();
    public loading: boolean;

    public get id() {
        return this._data?.id || '';
    }

    public readonly form = new FormGroup({
        id: new FormControl(''),
        name: new FormControl('', [Validators.required]),
        map_id: new FormControl('', [Validators.required]),
        assigned_user: new FormControl<User>(null),
        assigned_to: new FormControl(''),
        assigned_name: new FormControl(''),
        notes: new FormControl(''),
        map_rotation: new FormControl(0),
    });

    constructor(
        @Inject(MAT_DIALOG_DATA) private _data: ParkingSpace,
        private _dialog_ref: MatDialogRef<ParkingSpaceModalComponent>,
    ) {
        if (_data) this.form.patchValue(_data);
    }

    public async ngOnInit() {
        if (this._data.assigned_to) {
            const user = await showStaff(this._data.assigned_to).toPromise();
            if (user) {
                this.form.patchValue({
                    assigned_user: user,
                    assigned_to: user.email,
                    assigned_name: user.name,
                });
            }
        }
    }

    public postForm() {
        if (!this.form.valid) return;
        this.loading = true;
        const value = { ...this.form.getRawValue() };
        if (value.assigned_user) {
            value.assigned_to = value.assigned_user.email;
            value.assigned_name = value.assigned_user.name;
            delete value.assigned_user;
        }
        this._dialog_ref.disableClose = true;
        this.event.emit({ reason: 'done', metadata: value });
    }
}
